def solution(babbling):
    answer = 0
    diction = ["aya", "ye", "woo", "ma"]

    for keyword in babbling:
        for char in diction:
            keyword = keyword.replace(char," ")

        if keyword.strip() == "":
            answer += 1
    return answer

def solution(dots):
    def is_parallel(p1, p2, p3, p4):
        # 기울기 비교: (y2-y1)*(x4-x3) == (y4-y3)*(x2-x1)
        return (p2[1]-p1[1]) * (p4[0]-p3[0]) == (p4[1]-p3[1]) * (p2[0]-p1[0])

    A, B, C, D = dots

    if is_parallel(A, B, C, D): return 1
    if is_parallel(A, C, B, D): return 1
    if is_parallel(A, D, B, C): return 1

    return 0
